    """
    .. versionadded:: 2014.7.0

    List all ipset sets.

    CLI Example:

    .. code-block:: bash

        salt '*' ipset.list_sets

    """
    cmd = "ipset -l"
    out = __salt__["cmd.run"](cmd).split("\n")
    ret = {}
    for line in out:
